lexeditor_ff8_meters::Hp battle_gf_hp(unsigned slot)
{
    using namespace lexeditor_ff8_meters;
    if (!FF8_US_VERSION || slot >= 3 || ff8_externals.savemap == nullptr) return {};
    const auto character = ff8_externals.character_data_1CFE74C[slot];
    if (character >= CHAR_NUM) return {};
    const auto junctions = ff8_externals.savemap->chars[character].gfs;
    if (junctions == 0) return {};
    std::array<GuardianForce, 16> gfs{};
    for (unsigned id = 0; id < gfs.size(); ++id) {
        const auto &saved = ff8_externals.savemap->gfs[id];
        // 00495D80 computes this 12-byte GF record; +2 is its maximum HP.
        const auto maximum = *reinterpret_cast<const std::uint16_t *>(0x01CFF61A + id * 0x0C);
        gfs[id] = {{saved.HPs, maximum}, (saved.exists & 1) != 0};
    }
    // During a summon the damage handler updates the participant's +0x18,
    // NOT the saved GF HP. 004B0555 reads this same live pair for the HUD.
    const auto *stats = reinterpret_cast<const std::uint8_t *>(0x01CFF000 + slot * 0x1D0);
    Summon summon;
    if ((stats[0x1C] & 1) && stats[0x1D] >= 0x40 && stats[0x1D] < 0x50) {
        summon.id = stats[0x1D] - 0x40;
        summon.hp.current = *reinterpret_cast<const std::uint16_t *>(stats + 0x18);
        summon.hp.maximum = *reinterpret_cast<const std::uint16_t *>(stats + 0x1A);
    }
    return junctioned_gf_hp(junctions, gfs, summon);
}

void draw_battle_meter(const lexeditor_ff8_meters::Line &line,
    const sprite_viewport &v, ImU32 color)
{
    if (!line.visible) return;
    const auto x = [&](float value) { return scale_x(value * v.scale_x + v.offset_x); };
    const auto y = [&](float value) { return scale_y(value * v.scale_y + v.offset_y); };
    const ImVec2 lo(x(line.left), y(line.top));
    const ImVec2 hi(x(line.right), y(line.top + 1.0f));
    if (hi.x <= lo.x || hi.y <= lo.y) return;
    auto *draw = ImGui::GetForegroundDrawList();
    draw->AddRectFilled(lo, hi, IM_COL32(0, 0, 0, 255));
    if (line.fill_right > line.fill_left) {
        draw->AddRectFilled(ImVec2(x(line.fill_left), lo.y), ImVec2(x(line.fill_right), hi.y), color);
    }
}

